/*
 * FibreSeeker 3 G-code Inspector — single-file bundle builder
 *
 * Produces g-code-inspector.html: one self-contained file with the whole engine
 * inlined. Double-click it, pick .gcode files, get results. No server, no build
 * step needed to *use* it, no network access at any point.
 *
 *   node src/build_bundle.js
 *
 * Source of truth stays in src/*.js (the CLI requires them directly). The UI
 * shell lives in src/ui.template. This script only concatenates, so the bundle
 * can never drift from the engine as long as it is re-run after a src change.
 */
'use strict';
const fs = require('fs');
const path = require('path');

// Lives in src/, writes the deliverable one level up.
const DIR = path.join(__dirname, '..');
const OUT = path.join(DIR, 'g-code-inspector.html');
const TEMPLATE = path.join(DIR, 'src', 'ui.template');
const MARKER = '<!--LIBS-->';

// Order matters: inspector.js reads root.FS3.Dialect / root.FS3.Raster at load.
const LIBS = ['src/dialect.js', 'src/raster.js', 'src/inspector.js'];

function read(p) {
  return fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
}

// A literal "</script>" inside an inline script would end it early. None of the
// libs contain one today; assert rather than assume.
function assertInlinable(name, code) {
  if (/<\/script/i.test(code)) throw new Error(name + ' contains "</script>" and cannot be inlined');
  if (/<!--/.test(code)) throw new Error(name + ' contains "<!--" and cannot be inlined');
}

function render() {
  const tpl = read(TEMPLATE);
  if (tpl.indexOf(MARKER) < 0) throw new Error('marker ' + MARKER + ' missing from ui.template');

  const parts = LIBS.map(function (rel) {
    const code = read(path.join(DIR, rel));
    assertInlinable(rel, code);
    const banner = '/* ===== ' + rel + ' ===== */\n';
    return banner + code.trimEnd();
  });

  const inline = '<script>\n/* Bundled engine — generated by build_bundle.js from:\n' +
    '   ' + LIBS.join(', ') + '\n   Do not edit this file by hand; edit src/*.js and re-run the builder. */\n' +
    parts.join('\n\n') + '\n</script>';

  return tpl.replace(MARKER, inline);
}

function build() {
  const html = render();
  fs.writeFileSync(OUT, html);
  return html;
}

exports.render = render;
exports.build = build;

// Split the inline <script> blocks out of the bundle, for verification.
function inlineScripts(html) {
  var out = [], re = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi, m;
  while ((m = re.exec(html))) {
    if (/\bsrc\s*=/i.test(m[1])) continue;
    out.push(m[2]);
  }
  return out;
}

exports.inlineScripts = inlineScripts;
exports.LIBS = LIBS;
exports.OUT = OUT;

if (require.main === module) {
  const html = build();
  const kb = (Buffer.byteLength(html) / 1024).toFixed(1);
  const blocks = inlineScripts(html);
  const external = (html.match(/<script[^>]+\bsrc=/gi) || []).length;
  console.log('wrote ' + path.basename(OUT) + '  ' + kb + ' KB  ' +
    html.split('\n').length + ' lines');
  console.log('  inline <script> blocks: ' + blocks.length + '   external src= refs: ' + external);
  if (external !== 0) throw new Error('bundle still references external scripts');
  if (blocks.length !== 2) throw new Error('expected 2 inline blocks (engine + UI), got ' + blocks.length);
}
